CREATE TABLE pest_disease_data(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`name` varchar(255)  NOT NULL UNIQUE COMMENT 'Pest or disease name',`type` varchar(50)  NOT NULL COMMENT 'pest or disease',`scientific_name` varchar(255)  NULL,`description` text  NOT NULL,`affected_crops` text  NULL COMMENT 'JSON array of crop names',`risk_stages` text  NULL COMMENT 'JSON array of vulnerable growth stages',`temperature_min` DECIMAL(5,2)  NULL COMMENT 'Minimum temperature for risk (Celsius)',`temperature_max` DECIMAL(5,2)  NULL COMMENT 'Maximum temperature for risk (Celsius)',`humidity_min` INT  NULL COMMENT 'Minimum humidity for risk (%)',`humidity_max` INT  NULL COMMENT 'Maximum humidity for risk (%)',`rainfall_min` DECIMAL(6,2)  NULL COMMENT 'Minimum rainfall for risk (mm)',`severity` varchar(50)  NOT NULL COMMENT 'low, medium, high',`organic_treatments` text  NULL COMMENT 'JSON array of organic treatment options',`chemical_treatments` text  NULL COMMENT 'JSON array of chemical treatment options',`prevention_measures` text  NULL COMMENT 'JSON array of prevention measures',`timing_instructions` text  NULL COMMENT 'Application timing guidance',`data_source` varchar(255)  NULL COMMENT 'ICAR, state dept, etc',`last_updated` timestamp  NULL)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;